SELECT fn_cp_import_case('ordre-manifestation-declaree-debordement-limite', '{"slug": "ordre-manifestation-declaree-debordement-limite", "title": "Une centaine de personnes quitte le parcours déclaré", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures. Vous êtes positionnée en service d''ordre lors d''une manifestation déclarée dont le parcours a été fixé à l''avance, lorsqu''une centaine de manifestants quitte soudainement cet itinéraire convenu pour emprunter une avenue adjacente, ce mouvement s''effectuant sans violence apparente mais constituant un écart net par rapport au cadre initialement autorisé. Cette déviation, qui pourrait relever d''une simple réorientation spontanée sans intention hostile ou au contraire annoncer une dégradation plus sérieuse de la situation, nécessite une évaluation rapide de la nature de ce mouvement avant toute réaction.\n\nCette situation, où le calibrage de la réponse doit tenir compte de l''absence de violence constatée à ce stade tout en restant vigilant face à cet écart au cadre déclaré, impose de ne pas agir seule sur la base de votre seule appréciation individuelle de cet événement.\n\nCette configuration nécessite de rendre compte sans délai de ce développement à votre hiérarchie, cette remontée d''information restant essentielle pour qu''une décision coordonnée puisse être prise plutôt qu''une réaction isolée de votre part.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous la nature de ce mouvement avant toute réaction de votre part ?", "hint": "L''absence de violence apparente ne doit pas conduire à ignorer cet écart, mais l''évaluation doit rester mesurée avant toute réaction disproportionnée.", "perfect": "J''observe attentivement ce mouvement de foule sans réagir précipitamment, cette absence de violence apparente constituant un élément important pour calibrer ma propre appréciation de la situation.\n\nJe reste attentive aux indices qui pourraient distinguer une réorientation spontanée sans intention hostile d''un développement plus préoccupant nécessitant une vigilance accrue de ma part.\n\nJe consigne mentalement les éléments observables de ce mouvement, notamment sa direction précise et l''ambiance générale qui semble l''accompagner, ces observations étant utiles pour mon compte rendu.\n\nJe reste positionnée de manière à conserver une vision d''ensemble de la situation, cette posture d''observation restant préférable à une intervention précipitée sur la seule base de mon appréciation individuelle.", "points": [{"position": 1, "label": "Observer attentivement sans réagir précipitamment", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : absence de violence calibrant l''appréciation.", "groups": [{"position": 1, "keywords": ["observation attentive", "pas de précipitation", "violence absente"]}]}, {"position": 2, "label": "Rester attentive aux indices distinguant réorientation et développement préoccupant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Vigilance accrue si nécessaire.", "groups": [{"position": 1, "keywords": ["indices distingués", "réorientation spontanée", "développement préoccupant"]}]}, {"position": 3, "label": "Consigner mentalement les éléments observables pour le compte rendu", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Direction précise et ambiance générale.", "groups": [{"position": 1, "keywords": ["éléments consignés", "direction observée", "ambiance notée"]}]}, {"position": 4, "label": "Rester positionnée pour conserver une vision d''ensemble", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Préférable à une intervention précipitée.", "groups": [{"position": 1, "keywords": ["vision d''ensemble", "positionnement maintenu", "pas de précipitation"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment rendez-vous compte sans délai de ce développement sans agir seule sur la base de votre seule appréciation ?", "hint": "La remontée d''information rapide reste essentielle pour permettre une décision coordonnée plutôt qu''une réaction individuelle isolée face à cet écart au cadre déclaré.", "perfect": "Je transmets sans délai à ma hiérarchie ce développement, cette information devant remonter rapidement compte tenu de l''écart constaté par rapport au parcours initialement déclaré.\n\nJe décris factuellement ce que j''observe, sans interprétation personnelle excessive, cette rigueur restant nécessaire pour permettre une appréciation objective par les niveaux de décision appropriés.\n\nJe m''abstiens d''agir de ma propre initiative sur la seule base de mon appréciation individuelle, cette réserve étant essentielle dans l''attente d''instructions coordonnées adaptées à cette situation.\n\nJe reste disponible et attentive aux instructions qui pourraient m''être données suite à ce compte rendu, cette réactivité restant nécessaire pour exécuter la réponse coordonnée qui sera décidée.", "points": [{"position": 1, "label": "Transmettre sans délai ce développement à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : écart par rapport au parcours déclaré.", "groups": [{"position": 1, "keywords": ["transmission sans délai", "hiérarchie informée", "écart constaté"]}]}, {"position": 2, "label": "Décrire factuellement sans interprétation personnelle excessive", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur pour une appréciation objective.", "groups": [{"position": 1, "keywords": ["description factuelle", "pas d''interprétation excessive", "appréciation objective"]}]}, {"position": 3, "label": "S''abstenir d''agir de sa propre initiative sur sa seule appréciation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserve essentielle dans l''attente d''instructions coordonnées.", "groups": [{"position": 1, "keywords": ["pas d''action individuelle", "réserve essentielle", "instructions attendues"]}]}, {"position": 4, "label": "Rester disponible et attentive aux instructions données", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour exécuter la réponse coordonnée.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "instructions suivies", "réponse coordonnée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment maintenez-vous votre posture professionnelle face à ce groupe important qui s''écarte du cadre convenu ?", "hint": "Le maintien d''une posture professionnelle calme reste essentiel face à ce groupe nombreux, cette attitude pouvant influencer positivement l''évolution de la situation.", "perfect": "Je maintiens une posture calme et professionnelle face à ce groupe de manifestants, cette attitude pouvant contribuer à ne pas envenimer une situation qui reste, à ce stade, non violente.\n\nJe reste attentive à ne pas provoquer par mon comportement une escalade qui ne serait pas justifiée par les éléments objectifs actuellement observés dans ce mouvement de foule.\n\nJe communique si nécessaire avec mes collègues présents pour coordonner notre positionnement collectif, cette cohésion restant importante face à ce développement inattendu.\n\nJe reste prête à m''adapter rapidement si la situation venait à évoluer, cette flexibilité restant nécessaire tant que l''issue de ce mouvement demeure incertaine.", "points": [{"position": 1, "label": "Maintenir une posture calme et professionnelle face au groupe", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas envenimer une situation non violente.", "groups": [{"position": 1, "keywords": ["posture calme", "professionnalisme maintenu", "situation non violente"]}]}, {"position": 2, "label": "Ne pas provoquer une escalade non justifiée par les éléments observés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comportement n''aggravant pas la situation.", "groups": [{"position": 1, "keywords": ["pas d''escalade", "comportement maîtrisé", "éléments objectifs"]}]}, {"position": 3, "label": "Communiquer avec les collègues pour coordonner le positionnement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Cohésion importante face au développement inattendu.", "groups": [{"position": 1, "keywords": ["coordination avec collègues", "positionnement collectif", "cohésion nécessaire"]}]}, {"position": 4, "label": "Rester prête à s''adapter rapidement si la situation évolue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Flexibilité face à l''incertitude de l''issue.", "groups": [{"position": 1, "keywords": ["adaptation rapide", "flexibilité maintenue", "issue incertaine"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-rassemblement-non-declare-spontane', '{"slug": "ordre-rassemblement-non-declare-spontane", "title": "Le rassemblement s''est formé en deux heures sur les réseaux", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Vous êtes dépêchée sur une place publique où un rassemblement s''est formé en l''espace de deux heures à peine, suite à un appel diffusé sur les réseaux sociaux, ce rassemblement n''ayant fait l''objet d''aucune déclaration préalable et ne présentant à première vue aucun organisateur clairement identifiable parmi les nombreux participants pourtant pacifiques présents sur les lieux. Cette spontanéité, caractéristique de ce type de mobilisation contemporaine née de la diffusion rapide sur les réseaux sociaux, complique l''identification d''un interlocuteur unique avec lequel établir un dialogue structuré sur le déroulement de cet événement.\n\nCette absence d''organisateur formel, qui distingue ce rassemblement des manifestations classiques encadrées par une déclaration préalable, ne dispense pas pour autant de rechercher activement un ou plusieurs interlocuteurs susceptibles de représenter, même informellement, une partie de ces participants.\n\nCette situation nécessite de maintenir un dialogue avec ce rassemblement malgré cette absence d''organisateur identifié, cette communication restant essentielle pour accompagner sereinement le déroulement de cet événement spontané et pacifique.", "questions": [{"position": 1, "max_points": 5, "label": "Comment identifiez-vous un interlocuteur malgré l''absence d''organisateur formel de ce rassemblement spontané ?", "hint": "Cette recherche d''interlocuteur doit s''adapter à la spontanéité de ce rassemblement, plusieurs personnes pouvant jouer informellement ce rôle sans être des organisateurs déclarés.", "perfect": "Je recherche activement parmi les participants présents des personnes qui semblent jouer un rôle de coordination informelle, ces individus pouvant constituer des interlocuteurs utiles malgré l''absence d''organisation structurée.\n\nJe m''adresse directement et calmement au groupe pour identifier si certains participants souhaitent porter la parole au nom du rassemblement, cette démarche pouvant faire émerger un dialogue même informel.\n\nJe reste attentive à ne pas exiger un interlocuteur unique comme condition préalable au dialogue, cette rigidité ne correspondant pas à la nature spontanée de ce type de mobilisation contemporaine.\n\nJe m''appuie si nécessaire sur les informations disponibles concernant l''appel initial diffusé sur les réseaux sociaux, cette origine pouvant orienter vers d''éventuels initiateurs de ce mouvement.", "points": [{"position": 1, "label": "Rechercher des personnes jouant un rôle de coordination informelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : interlocuteurs utiles malgré l''absence d''organisation.", "groups": [{"position": 1, "keywords": ["coordination informelle", "interlocuteurs identifiés", "absence d''organisation"]}]}, {"position": 2, "label": "S''adresser directement au groupe pour faire émerger un dialogue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarche pouvant faire émerger un dialogue informel.", "groups": [{"position": 1, "keywords": ["adresse directe", "dialogue informel", "parole recherchée"]}]}, {"position": 3, "label": "Ne pas exiger un interlocuteur unique comme condition préalable", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigidité ne correspondant pas à la nature spontanée.", "groups": [{"position": 1, "keywords": ["pas d''exigence rigide", "nature spontanée", "mobilisation contemporaine"]}]}, {"position": 4, "label": "S''appuyer sur les informations de l''appel initial diffusé en ligne", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Orienter vers d''éventuels initiateurs.", "groups": [{"position": 1, "keywords": ["appel initial", "initiateurs recherchés", "origine du mouvement"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment maintenez-vous le dialogue avec ce rassemblement pacifique malgré cette absence d''organisation structurée ?", "hint": "Le maintien du dialogue reste essentiel pour accompagner sereinement cet événement, cette communication continue devant s''adapter à la configuration particulière de ce rassemblement spontané.", "perfect": "Je maintiens une communication ouverte et régulière avec les participants, cette approche restant adaptée à ce rassemblement pacifique malgré l''absence d''interlocuteur unique clairement établi.\n\nJe reste attentive à l''évolution de l''ambiance générale de ce rassemblement, cette vigilance continue permettant d''ajuster mon propre comportement en fonction du déroulement de cet événement spontané.\n\nJe communique clairement les informations utiles aux participants, notamment sur d''éventuelles contraintes de sécurité ou d''organisation de l''espace public que cette occupation pourrait engendrer.\n\nJe reste disponible pour répondre aux questions des participants sur le déroulement de cette intervention, cette transparence pouvant contribuer à maintenir un climat serein tout au long de cet événement.", "points": [{"position": 1, "label": "Maintenir une communication ouverte et régulière avec les participants", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : approche adaptée malgré l''absence d''interlocuteur unique.", "groups": [{"position": 1, "keywords": ["communication ouverte", "approche adaptée", "interlocuteur absent"]}]}, {"position": 2, "label": "Rester attentive à l''évolution de l''ambiance générale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Vigilance continue ajustant le comportement.", "groups": [{"position": 1, "keywords": ["ambiance surveillée", "vigilance continue", "comportement ajusté"]}]}, {"position": 3, "label": "Communiquer clairement les informations utiles sur la sécurité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contraintes de sécurité ou d''organisation de l''espace.", "groups": [{"position": 1, "keywords": ["informations communiquées", "contraintes de sécurité", "espace public"]}]}, {"position": 4, "label": "Rester disponible pour répondre aux questions des participants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence maintenant un climat serein.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "transparence apportée", "climat serein"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette situation particulière à votre hiérarchie pour orienter la suite de cette intervention ?", "hint": "Cette configuration spontanée et non déclarée nécessite un compte rendu précis permettant à votre hiérarchie d''apprécier la suite appropriée à donner à cette intervention.", "perfect": "Je transmets à ma hiérarchie une description précise de cette situation, notamment l''absence de déclaration préalable et le caractère pacifique constaté de ce rassemblement spontané.\n\nJe reste attentive à communiquer l''ampleur réelle de ce rassemblement et son évolution probable, ces éléments pouvant orienter la décision sur les moyens à engager pour accompagner cet événement.\n\nJe consigne les éventuelles tentatives d''identification d''interlocuteurs que j''ai pu mener, cette information complétant utilement mon compte rendu sur cette configuration particulière.\n\nJe reste attentive aux instructions qui pourraient m''être données suite à ce compte rendu, cette réactivité restant nécessaire pour ajuster mon action selon la décision qui sera prise.", "points": [{"position": 1, "label": "Transmettre une description précise incluant l''absence de déclaration", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : caractère pacifique constaté du rassemblement.", "groups": [{"position": 1, "keywords": ["description précise", "absence de déclaration", "caractère pacifique"]}]}, {"position": 2, "label": "Communiquer l''ampleur réelle et l''évolution probable", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Orienter la décision sur les moyens à engager.", "groups": [{"position": 1, "keywords": ["ampleur communiquée", "évolution probable", "moyens à engager"]}]}, {"position": 3, "label": "Consigner les tentatives d''identification d''interlocuteurs menées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information complétant le compte rendu.", "groups": [{"position": 1, "keywords": ["tentatives consignées", "compte rendu complété", "configuration particulière"]}]}, {"position": 4, "label": "Rester attentive aux instructions données suite à ce compte rendu", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour ajuster l''action selon la décision.", "groups": [{"position": 1, "keywords": ["instructions attendues", "action ajustée", "décision suivie"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-filtrage-acces-refus-personne', '{"slug": "ordre-filtrage-acces-refus-personne", "title": "Il refuse l''inspection de son sac et bloque la file", "theme_slug": "ordre-public", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 18 heures. Vous êtes positionnée au filtrage de l''entrée d''un stade où un homme refuse catégoriquement de se soumettre à l''inspection de son sac prévue par le dispositif de sécurité de cet événement, ce refus, bien que légitime sur le plan strictement juridique puisqu''aucune obligation générale ne l''y contraint, ayant pour effet concret de bloquer la file d''attente et de faire monter une tension perceptible parmi les autres spectateurs impatients derrière lui. Cette situation, où un droit individuellement légitime entre en tension directe avec la nécessité de préserver la fluidité de ce flux d''entrée pour l''ensemble des autres spectateurs, nécessite une gestion qui ne contraigne pas cette personne tout en explicitant clairement les conséquences pratiques de son choix.\n\nCette configuration, caractéristique des limites du filtrage de sécurité dans ce type d''événement où l''accès reste normalement conditionné à cette inspection sans que son refus ne puisse être imposé par la force, impose de trouver un équilibre entre le respect de ce refus et la préservation du bon déroulement de cet accès pour les autres.\n\nCette situation nécessite d''expliquer clairement à cette personne les conséquences de son refus, notamment l''impossibilité d''accéder à cet événement dans ces conditions, sans pour autant chercher à le contraindre à cette inspection qu''il n''est pas légalement tenu d''accepter.", "questions": [{"position": 1, "max_points": 5, "label": "Comment expliquez-vous clairement à cet homme les conséquences de son refus sans chercher à le contraindre ?", "hint": "Ce refus, légitime en droit, doit être respecté tout en explicitant clairement ses conséquences pratiques sur l''accès à cet événement.", "perfect": "J''explique clairement à cet homme que son refus, bien que légitime, aura pour conséquence de lui refuser l''accès à ce stade dans le cadre du dispositif de sécurité mis en place pour cet événement.\n\nJe reste respectueuse de son droit à refuser cette inspection, cette contrainte physique n''étant en aucun cas envisageable face à un refus qui reste juridiquement légitime de sa part.\n\nJe reste factuelle dans mon explication, sans dramatiser excessivement cette situation qui relève d''un choix personnel dont il doit simplement connaître les conséquences pratiques.\n\nJe lui laisse le temps de reconsidérer sa position s''il le souhaite, cette possibilité de changement d''avis restant ouverte sans pour autant que je n''exerce de pression indue sur sa décision.", "points": [{"position": 1, "label": "Expliquer clairement que le refus entraîne l''impossibilité d''accéder à l''événement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conséquence du refus dans le dispositif de sécurité.", "groups": [{"position": 1, "keywords": ["conséquence expliquée", "accès refusé", "dispositif de sécurité"]}]}, {"position": 2, "label": "Rester respectueuse de son droit à refuser sans contrainte physique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Refus juridiquement légitime.", "groups": [{"position": 1, "keywords": ["droit respecté", "pas de contrainte physique", "refus légitime"]}]}, {"position": 3, "label": "Rester factuelle sans dramatiser excessivement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Choix personnel avec conséquences pratiques connues.", "groups": [{"position": 1, "keywords": ["factuelle sans drame", "choix personnel", "conséquences connues"]}]}, {"position": 4, "label": "Laisser le temps de reconsidérer sa position sans pression indue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Changement d''avis possible sans pression.", "groups": [{"position": 1, "keywords": ["temps laissé", "changement possible", "pas de pression indue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la tension perceptible parmi les autres spectateurs impatientés par ce blocage ?", "hint": "Cette file bloquée génère une tension parmi les autres spectateurs, cette dimension collective nécessitant une gestion qui ne se limite pas au seul dialogue avec la personne refusante.", "perfect": "Je reste attentive à la tension grandissante parmi les autres spectateurs, cette impatience méritant une gestion qui ne néglige pas leur propre expérience de cet événement.\n\nJe cherche si possible une solution pratique pour ne pas bloquer complètement cette file, comme orienter les autres spectateurs vers une autre entrée disponible pendant que cette situation se résout.\n\nJe communique brièvement aux personnes qui attendent sur les raisons de ce ralentissement, cette transparence pouvant atténuer quelque peu leur impatience face à ce blocage temporaire.\n\nJe reste professionnelle face à d''éventuelles réactions impatientes de ces autres spectateurs, cette maîtrise restant nécessaire pour ne pas ajouter de tension supplémentaire à cette situation déjà délicate.", "points": [{"position": 1, "label": "Rester attentive à la tension grandissante parmi les autres spectateurs", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : expérience des autres spectateurs à ne pas négliger.", "groups": [{"position": 1, "keywords": ["tension notée", "autres spectateurs", "expérience préservée"]}]}, {"position": 2, "label": "Chercher une solution pratique pour ne pas bloquer complètement la file", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Orienter vers une autre entrée disponible.", "groups": [{"position": 1, "keywords": ["solution pratique", "autre entrée", "file non bloquée"]}]}, {"position": 3, "label": "Communiquer brièvement sur les raisons du ralentissement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence atténuant l''impatience.", "groups": [{"position": 1, "keywords": ["communication brève", "raisons expliquées", "impatience atténuée"]}]}, {"position": 4, "label": "Rester professionnelle face aux réactions impatientes des autres", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Maîtrise ne pas ajouter de tension.", "groups": [{"position": 1, "keywords": ["professionnalisme maintenu", "pas de tension ajoutée", "situation délicate"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous cette situation une fois la décision de cet homme définitivement arrêtée ?", "hint": "Quelle que soit l''issue de cette situation, une conclusion claire et professionnelle reste nécessaire pour permettre à la file de reprendre normalement son cours.", "perfect": "Je m''assure que cet homme a bien compris les conséquences définitives de son choix, cette clarté finale évitant toute ambiguïté sur la suite de cette situation.\n\nS''il maintient son refus, je l''invite courtoisement à s''écarter de la file pour permettre aux autres spectateurs de reprendre normalement leur progression vers l''entrée de ce stade.\n\nJe reste courtoise jusqu''au terme de cet échange, cette attitude professionnelle restant appropriée indépendamment de l''issue de cette situation qui relève de son choix personnel.\n\nJe consigne si nécessaire cet incident pour le suivi du dispositif de sécurité, cette information pouvant être utile pour la suite de la gestion de cet événement.", "points": [{"position": 1, "label": "S''assurer qu''il a bien compris les conséquences définitives de son choix", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : clarté finale évitant toute ambiguïté.", "groups": [{"position": 1, "keywords": ["compréhension vérifiée", "conséquences définitives", "clarté finale"]}]}, {"position": 2, "label": "Inviter courtoisement à s''écarter pour permettre la reprise de la file", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Progression normale des autres spectateurs.", "groups": [{"position": 1, "keywords": ["invitation courtoise", "file reprise", "autres spectateurs"]}]}, {"position": 3, "label": "Rester courtoise jusqu''au terme de cet échange", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attitude professionnelle indépendante de l''issue.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "professionnalisme", "issue indépendante"]}]}, {"position": 4, "label": "Consigner cet incident pour le suivi du dispositif de sécurité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile pour la gestion de l''événement.", "groups": [{"position": 1, "keywords": ["incident consigné", "dispositif de sécurité", "gestion de l''événement"]}]}]}]}'::jsonb);
